<a class="back-link" href="<?= e(url(['page'=>'books'])) ?>">← Voltar ao acervo</a>
<div class="page-heading"><div><p class="eyebrow">LIVRO #<?= str_pad((string)$id,4,'0',STR_PAD_LEFT) ?> <?= $book['archived'] ? '· ARQUIVADO' : '' ?></p><h1><?= e($book['title']) ?></h1><p><?= e($book['author']) ?></p></div><?php if (!$book['archived']): ?><a class="btn btn-outline-primary" href="<?= e(url(['page'=>'edit','id'=>$id])) ?>">Editar cadastro</a><?php endif; ?></div>
<div class="row g-4 mb-4"><div class="col-lg-7"><section class="panel h-100">
<div class="book-summary"><div><span>Disponível no estoque</span><strong><?= $book['quantity'] ?> <small>un.</small></strong></div><div><span>Preço de venda</span><strong><?= money($book['price_cents']) ?></strong></div></div>
<?php if ($book['quantity'] <= $book['minimum_stock'] && !$book['archived']): ?><div class="alert alert-warning mt-3">Estoque baixo: o mínimo definido é <?= $book['minimum_stock'] ?> unidade(s).</div><?php endif; ?>
<dl class="detail-grid mt-4"><?php foreach (['category'=>'Categoria','publisher'=>'Editora','isbn'=>'ISBN','condition'=>'Conservação','location'=>'Localização','minimum_stock'=>'Estoque mínimo'] as $key=>$label): ?><div><dt><?= $label ?></dt><dd><?= e($book[$key] === '' ? 'Não informado' : $book[$key]) ?></dd></div><?php endforeach; ?></dl>
<?php if ($book['notes']): ?><h2 class="h6">Observações</h2><p class="preserve-lines"><?= e($book['notes']) ?></p><?php endif; ?>
<div class="archive-area"><form method="post" <?= !$book['archived'] ? 'data-confirm="Arquivar este livro? O cadastro e o histórico serão preservados."' : '' ?>><?php csrf(); ?><input type="hidden" name="action" value="<?= $book['archived'] ? 'restore' : 'archive' ?>"><button class="btn btn-sm btn-outline-secondary" <?= !$book['archived'] && $book['quantity'] > 0 ? 'disabled' : '' ?>><?= $book['archived'] ? 'Reativar livro' : 'Arquivar livro' ?></button><?php if (!$book['archived'] && $book['quantity'] > 0): ?><span class="form-text d-block mt-2">O arquivamento fica disponível quando o saldo estiver zerado.</span><?php endif; ?></form></div>
</section></div>
<div class="col-lg-5"><section class="panel h-100"><h2>Movimentar estoque</h2><p class="section-description">Cada alteração fica registrada no histórico.</p>
<?php if ($book['archived']): ?><div class="empty-state compact"><h3>Este livro está arquivado</h3><p>Reative o cadastro para registrar novas movimentações.</p></div><?php else: ?>
<form method="post" id="movement-form"><?php csrf(); ?><input type="hidden" name="action" value="move">
    <div class="mb-3"><label class="form-label" for="type">Tipo *</label><select class="form-select" name="type" id="type" required><option value="entrada" <?= field($input,'type')==='entrada' ? 'selected' : '' ?>>Entrada</option><option value="saida" <?= field($input,'type')==='saida' ? 'selected' : '' ?>>Saída</option></select></div>
    <div class="row g-3 mb-3"><div class="col-sm-4"><label class="form-label" for="quantity">Quantidade *</label><input class="form-control" type="number" name="quantity" id="quantity" min="1" max="1000000" step="1" required value="<?= e(field($input,'quantity','1')) ?>"></div><div class="col-sm-8"><label class="form-label" for="reason">Motivo *</label><select class="form-select" name="reason" id="reason" required><?php foreach (\Sebook\Inventory::REASONS as $type=>$reasons): ?><optgroup label="<?= $type==='entrada' ? 'Entradas' : 'Saídas' ?>" data-type="<?= $type ?>"><?php foreach ($reasons as $reason): ?><option value="<?= e($reason) ?>" <?= field($input,'reason')===$reason && field($input,'type','entrada')===$type ? 'selected' : '' ?>><?= e($reason) ?></option><?php endforeach; ?></optgroup><?php endforeach; ?></select></div></div>
    <div class="mb-3"><label class="form-label" for="note">Observação</label><textarea class="form-control" id="note" name="note" maxlength="500" rows="3" placeholder="Detalhes da entrada ou saída."><?= e(field($input,'note')) ?></textarea></div>
    <button class="btn btn-primary w-100">Registrar movimentação</button>
</form><?php endif; ?></section></div></div>
